function predictCrashEvent(featuresArray) {
    const probs = scoreCrashModel(featuresArray);
    let maxIdx = 0;
    for (let i = 1; i < probs.length; i++) {
        if (probs[i] > probs[maxIdx]) {
            maxIdx = i;
        }
    }
    const labels = ["NORMAL", "PHONE_DROP", "SEVERE_CRASH"];
    return {
        classId: maxIdx,
        label: labels[maxIdx],
        probabilities: {
            normal: Number(probs[0].toFixed(3)),
            phone_drop: Number(probs[1].toFixed(3)),
            severe_crash: Number(probs[2].toFixed(3))
        }
    };
}
